#ifndef FE2_PEOPLE_TABLES_H
#define FE2_PEOPLE_TABLES_H

/* Tables generated by tools/people_tables_c.py into people_tables_data.h. */
#include <stdint.h>

#include "objects.h"

enum {
    PEOPLE_TABLES_AT = 0x2d1,             /* image offset of people_tables[0] */
    PEOPLE_TABLE_BYTES = 0x3a0 - 0x2d1,
    /* Image offsets of the tables in it. */
    T_INSTALLED = 0x2d1,               /* byte by the roll's top nibble */
    T_DRIVE_MASS = 0x2e1,              /* word by drive */
    T_DRIVE_FUEL = 0x2fd,              /* byte by drive */
    T_FUEL_SHARE = 0x30c,              /* word by marker */
    T_CAPACITY_ROLL = 0x326,           /* byte by marker */
    T_EQUIPMENT = 0x332,               /* byte by band */
    T_EQUIPMENT_COST = 0x33a,          /* word by band */
    T_EQUIPMENT_BAND = 0x33c,          /* word by band */
    T_DRIVE_CLASS = 0x350,             /* byte by drive */
    T_NAME_TYPE = 0x35f,               /* byte by marker */
    T_VARIANTS = 0x36c,                /* words */
    T_DAMAGE = 0x394                   /* word at the byte offset model - 6 */
};

extern const uint8_t *fe2_people_template;
extern const uint8_t *people_tables;

/* Image-offset reads (indices stay inside the tables: see the README). */
static inline uint8_t people_table_byte(unsigned at)
{
    return people_tables[at - PEOPLE_TABLES_AT];
}

static inline uint16_t people_table_word(unsigned at)
{
    return (uint16_t)(people_tables[at - PEOPLE_TABLES_AT] | people_tables[at - PEOPLE_TABLES_AT + 1] << 8);
}

#endif
